1	'use client';
2	import {useMapControlsStore} from '@/app/store/mapControlsStore';
3	import {useOverlayStore} from '@/app/store/overlayStore';
4	import {GEODATA_URL} from '@/app/utils/api/constants';
5	import {FilterSpecification} from 'maplibre-gl';
6	import {useMemo} from 'react';
7	import {Layer, Source} from 'react-map-gl/maplibre';
8	import {
9	  SENTINEL_EMPTY_ARRAY,
10	  SENTINEL_EMPTY_VALUE,
11	  HIGHLIGHT_LINE_COLOR,
12	  HIGHLIGHT_LINE_WIDTH,
13	} from '@/app/constants/map/layerStyle';
14	import {HIGHLIGHT_FILL_COLOR, SELECTED_LINE_STYLE} from '@/app/constants/map/overlayLayerStyles';
15	import {
16	  CANONICAL_LAYER_IDS,
17	  COUNTY_SOURCE_ID,
18	  MAP_LAYER_ANCHOR_IDS,
19	} from '@/app/constants/map/layerIds';
20	
21	export const CountyLayers = ({layerBeforeId}: {layerBeforeId: string}) => {
22	  const mapOptions = useMapControlsStore(state => state.mapOptions);
23	  const hoveredCountyGeoid = useMapControlsStore(state => state.hoveredCountyGeoid);
24	  const paintConstraint = useOverlayStore(state => state.paintConstraint);
25	  const countyMaskId =
26	    paintConstraint?.overlayId === COUNTY_SOURCE_ID ? paintConstraint.featureId : null;
27	
28	  const countyFilter = useMemo(() => {
29	    // If stateFipsSet is set and not empty, match any of its values
30	    const stateFpsArray =
31	      mapOptions.stateFipsSet?.size && mapOptions.stateFipsSet.size > 0
32	        ? Array.from(mapOptions.stateFipsSet)
33	        : SENTINEL_EMPTY_ARRAY;
34	    return [
35	      'match',
36	      ['slice', ['get', 'GEOID'], 0, 2],
37	      stateFpsArray,
38	      true,
39	      false,
40	    ] as FilterSpecification;
41	  }, [mapOptions.stateFipsSet]);
42	
43	  return (
44	    <>
45	      <Source
46	        id={COUNTY_SOURCE_ID}
47	        type="vector"
48	        url={`pmtiles://${GEODATA_URL}/basemaps/tiger/tiger2023/tl_2023_us_county_full.pmtiles`}
49	        promoteId="GEOID"
50	      >
51	        <Layer
52	          id={CANONICAL_LAYER_IDS.COUNTIES.BOUNDARY}
53	          beforeId={layerBeforeId}
54	          type="line"
55	          source-layer="tl_2023_us_county"
56	          paint={{
57	            'line-color': '#444',
58	            'line-opacity': 0.9,
59	            'line-width': ['interpolate', ['exponential', 1.6], ['zoom'], 6, 1.5, 9, 3, 18, 5],
60	          }}
61	          layout={{
62	            visibility: mapOptions.showCountyBoundaries ? 'visible' : 'none',
63	          }}
64	          filter={countyFilter}
65	        />
66	        <Layer
67	          id={CANONICAL_LAYER_IDS.COUNTIES.FILL}
68	          beforeId={CANONICAL_LAYER_IDS.COUNTIES.BOUNDARY}
69	          type="fill"
70	          source-layer="tl_2023_us_county"
71	          paint={{
72	            'fill-color': '#fff',
73	            'fill-opacity': 0,
74	          }}
75	          filter={countyFilter}
76	        />
77	        <Layer
78	          id={CANONICAL_LAYER_IDS.COUNTIES.HIGHLIGHT}
79	          beforeId={MAP_LAYER_ANCHOR_IDS.hover}
80	          type="line"
81	          source-layer="tl_2023_us_county"
82	          paint={{
83	            'line-color': HIGHLIGHT_LINE_COLOR,
84	            'line-width': HIGHLIGHT_LINE_WIDTH,
85	          }}
86	          filter={
87	            hoveredCountyGeoid
88	              ? ['==', ['get', 'GEOID'], hoveredCountyGeoid]
89	              : ['==', ['get', 'GEOID'], SENTINEL_EMPTY_VALUE]
90	          }
91	        />
92	        {/* Hover highlight while choosing a county paint mask (feature-state hover) */}
93	        <Layer
94	          id={CANONICAL_LAYER_IDS.COUNTIES.HOVER_FILL}
95	          beforeId={MAP_LAYER_ANCHOR_IDS.hover}
96	          type="fill"
97	          source-layer="tl_2023_us_county"
98	          paint={HIGHLIGHT_FILL_COLOR}
99	          filter={countyFilter}
100	        />
101	        {/* Dim everything outside the active county paint mask.
102	            NOTE: must be direct children of <Source> (no fragment) so
103	            react-map-gl can inject the source prop. */}
104	        {countyMaskId && (
105	          <Layer
106	            id={CANONICAL_LAYER_IDS.COUNTIES.MASK}
107	            beforeId={MAP_LAYER_ANCHOR_IDS.hover}
108	            type="fill"
109	            source-layer="tl_2023_us_county"
110	            paint={{
111	              'fill-color': '#FFFFFF',
112	              'fill-opacity': 0.75,
113	            }}
114	            filter={
115	              [
116	                'all',
117	                countyFilter,
118	                ['!', ['==', ['get', 'GEOID'], countyMaskId]],
119	              ] as FilterSpecification
120	            }
121	          />
122	        )}
123	        {countyMaskId && (
124	          <Layer
125	            id={CANONICAL_LAYER_IDS.COUNTIES.SELECTED}
126	            beforeId={MAP_LAYER_ANCHOR_IDS.hover}
127	            type="line"
128	            source-layer="tl_2023_us_county"
129	            paint={SELECTED_LINE_STYLE}
130	            filter={['==', ['get', 'GEOID'], countyMaskId]}
131	          />
132	        )}
133	        <Layer
134	          id={CANONICAL_LAYER_IDS.COUNTIES.LABELS}
135	          beforeId={mapOptions.prominentCountyNames ? undefined : MAP_LAYER_ANCHOR_IDS.counties}
136	          type="symbol"
137	          source-layer="tl_2023_us_county_label"
138	          minzoom={6}
139	          layout={{
140	            'text-field': ['get', 'NAME'],
141	            'text-font': mapOptions.prominentCountyNames ? ['Barlow Bold'] : ['Barlow Regular'],
142	            'text-size': ['interpolate', ['linear'], ['zoom'], 5, 8, 8, 12, 12, 16],
143	            'text-transform': 'uppercase',
144	            'text-letter-spacing': 0.1,
145	            'text-max-width': 12,
146	            'text-padding': ['interpolate', ['linear'], ['zoom'], 5, 3, 8, 7, 12, 11],
147	          }}
148	          paint={{
149	            'text-color': '#666',
150	            'text-halo-color': '#ffffff',
151	            'text-halo-width': 2,
152	          }}
153	          filter={countyFilter}
154	        />
155	      </Source>
156	    </>
