export const AREA_SELECT_TOOLS: ActiveTool[] = [
  ACTIVE_TOOLS.BRUSH,
  ACTIVE_TOOLS.ERASER,
  ACTIVE_TOOLS.INSPECTOR,
];
export const POINT_SELECT_TOOLS: ActiveTool[] = [ACTIVE_TOOLS.SHATTER];
export const ALL_BRUSHING_TOOLS: ActiveTool[] = [...AREA_SELECT_TOOLS, ...POINT_SELECT_TOOLS];
export const TOOLTIP_TOOLS: ActiveTool[] = [ACTIVE_TOOLS.INSPECTOR];
export const MUTATION_TOOLS: ActiveTool[] = [
  ACTIVE_TOOLS.BRUSH,
  ACTIVE_TOOLS.ERASER,
  ACTIVE_TOOLS.SHATTER,
];

export const EMPTY_FEATURE_ARRAY: MapGeoJSONFeature[] = [];

/**
 * The clickable layer while selecting a paint-mask area. The built-in county
 * layer (COUNTY_SOURCE_ID sentinel) uses its always-on invisible fill layer;
 * overlays use their dedicated click layer.
 */
export const getSelectingClickLayer = (selectingLayerId: string) =>
  selectingLayerId === COUNTY_SOURCE_ID
    ? CANONICAL_LAYER_IDS.COUNTIES.FILL
    : `overlay-click-${selectingLayerId}`;
