 */

/**
 * Get the layer IDs to paint based on whether we have
 * a shatterable map (based on whether a child layer is
 * present) and the active tool. If the active tool is
 * shatter, we only want to paint the shatterable layer.
 *
 * @param child_layer - string | undefined | null, the child layer
 * @param activeTool - ActiveTool, the active tool
 * @returns string[], the layer IDs to paint
 */
function getLayerIdsToPaint(child_layer: string | undefined | null, activeTool: ActiveTool) {
  if (activeTool === ACTIVE_TOOLS.SHATTER) {
    return [BLOCK_HOVER_LAYER_ID];
  }

  return child_layer
    ? [
        BLOCK_POINTS_LAYER_ID,
        BLOCK_POINTS_LAYER_ID_CHILD,
        BLOCK_HOVER_LAYER_ID,
        BLOCK_HOVER_LAYER_ID_CHILD,
      ]
    : [BLOCK_POINTS_LAYER_ID, BLOCK_HOVER_LAYER_ID];
}

// Cached per-session: access level doesn't change after document load.
let _canMutate: boolean | null = null;
const canMutateAssignments = () => {
  if (_canMutate === null) {
    _canMutate = useMapStore.getState().mapDocument?.access === ACCESS_STATES.EDIT;
  }
  return _canMutate;
};
// Reset when document changes (called from subscription teardown / new document load).
// Store the unsubscribe so HMR can dispose the previous subscription; otherwise every
// dev-mode hot reload stacks another listener on top of the Zustand store.
const _canMutateUnsubscribe = useMapStore.subscribe(
  state => state.mapDocument,
  () => {
    _canMutate = null;
  }
);
if (typeof module !== 'undefined' && (module as any).hot) {
  (module as any).hot.dispose(() => {
    _canMutateUnsubscribe();
  });
}

