private updateCoalitionMaxValues(rows: SummaryTable) {
  const maxValues = {...(this.zoneStats.maxValues ?? {})} as Record<string, number>;
  Object.values(COALITION_UNIVERSES).forEach(universe => {
    const variable = COALITION_VARIABLE_BY_UNIVERSE[universe];
    const pctVariable = `${variable}_pct`;
    const rawMax = Math.max(0, ...rows.map(row => asNumericRecord(row)[variable] ?? 0));
    const pctMax = Math.max(
      0,
      ...rows
        .map(row => asNumericRecord(row)[pctVariable])
        .filter(value => Number.isFinite(value))
    );
    maxValues[variable] = rawMax;
    maxValues[pctVariable] = pctMax;
  });
  this.zoneStats.maxValues = maxValues as MaxValues & Record<string, number>;
}
/**
 * Gets the filtered data for a given ID.
 *
 * @param id - The ID to filter by.
 * @returns The filtered data.
 */
getFiltered(id: string): MapGeoJSONFeature[] {
  if (!this.table) {
    return [];
  }
  const cached = this.filteredCache.get(id);
  if (cached) {
    return cached;
  }
  const ids = this.table
    .select(this.id_col, 'sourceLayer', 'total_pop_20')
    .params({
      id: id,
      vtdId: `vtd:${id}`,
    })
    .filter(
      (row: TableRow, $: {id: string; vtdId: string}) =>
        op.startswith(row['path'], $.id) || op.startswith(row['path'], $.vtdId)
    )
    .objects()
    .map((properties: TableRow) => ({
      id: properties.path,
      sourceLayer: properties.sourceLayer,
      source: BLOCK_SOURCE_ID,
      properties,
    })) as MapGeoJSONFeature[];
  this.filteredCache.set(id, ids);
  return ids;
}

/**
 * Whether the currently loaded units span more than one county. Early-exits
 * on the second distinct county FIPS found — callers only need "more than
 * one," never the actual count or the list, so there's no reason to scan
 * past that. `path` values look like `vtd:48001000001` (or without a type
 * prefix for some geography levels) — the state+county FIPS is always the
 * 5 digits right after any `<type>:` prefix.
 */
spansMultipleCounties(): boolean {
  if (!this.table) return false;
  const paths = this.table.array(this.id_col) as string[];
  if (!paths.length) return false;
  const toGeoid = (path: string) =>
    path.includes(':') ? path.slice(path.indexOf(':') + 1) : path;
  const firstCountyFips = toGeoid(paths[0]).slice(0, 5);
  for (let i = 1; i < paths.length; i++) {
    if (!toGeoid(paths[i]).startsWith(firstCountyFips)) return true;
  }
  return false;
}

